class _Authenticator:
    """Private class to provide en/decoding
            for base64-based authentication conversation.
    """

    def __init__(self, mechinst):
        self.mech = mechinst

    def process(self, data):
        ret = self.mech(self.decode(data))
        if ret is None:
            return b'*'
        return self.encode(ret)

    def encode(self, inp):
        oup = b''
        if isinstance(inp, str):
            inp = inp.encode('utf-8')
        while inp:
            if len(inp) > 48:
                t = inp[:48]
                inp = inp[48:]
            else:
                t = inp
                inp = b''
            e = binascii.b2a_base64(t)
            if e:
                oup = oup + e[:-1]
        return oup

    def decode(self, inp):
        if not inp:
            return b''
        return binascii.a2b_base64(inp)

def ParseFlags(resp):
    """Convert IMAP4 flags response to python tuple."""
    mo = Flags.match(resp)
    if not mo:
        return ()
    return tuple(mo.group('flags').split())

def Time2Internaldate(date_time):
    """Convert date_time to IMAP4 INTERNALDATE representation.

    Return string in form: '"DD-Mmm-YYYY HH:MM:SS +HHMM"'.  The
    date_time argument can be a number (int or float) representing
    seconds since epoch (as returned by time.time()), a 9-tuple
    representing local time, an instance of time.struct_time (as
    returned by time.localtime()), an aware datetime instance or a
    double-quoted string.  In the last case, it is assumed to already
    be in the correct format.
    """
    if isinstance(date_time, (int, float)):
        dt = datetime.fromtimestamp(date_time, timezone.utc).astimezone()
    elif isinstance(date_time, tuple):
        try:
            gmtoff = date_time.tm_gmtoff
        except AttributeError:
            if time.daylight:
                dst = date_time[8]
                if dst == -1:
                    dst = time.localtime(time.mktime(date_time))[8]
                gmtoff = -(time.timezone, time.altzone)[dst]
            else:
                gmtoff = -time.timezone
        delta = timedelta(seconds=gmtoff)
        dt = datetime(*date_time[:6], tzinfo=timezone(delta))
    elif isinstance(date_time, datetime):
        if date_time.tzinfo is None:
            raise ValueError('date_time must be aware')
        dt = date_time
    elif isinstance(date_time, str) and (date_time[0], date_time[-1]) == ('"', '"'):
        return date_time
    else:
        raise ValueError('date_time not of a known type')
    fmt = '"%d-{}-%Y %H:%M:%S %z"'.format(Months[dt.month])
    return dt.strftime(fmt)

def readline(self):
    """Read line from remote."""
    line = self.file.readline(_MAXLINE + 1)
    if len(line) > _MAXLINE:
        raise self.error('got more than %d bytes' % _MAXLINE)
    return line

def shutdown(self):
    """Close I/O established in "open"."""
    self.file.close()
    try:
        self.sock.shutdown(socket.SHUT_RDWR)
    except OSError as exc:
        if exc.errno != errno.ENOTCONN and getattr(exc, 'winerror', 0) != 10022:
            raise
    finally:
        self.sock.close()

def recent(self):
    """Return most recent 'RECENT' responses if any exist,
        else prompt server for an update using the 'NOOP' command.

        (typ, [data]) = <instance>.recent()

        'data' is None if no new messages,
        else list of RECENT responses, most recent last.
        """
    name = 'RECENT'
    (typ, dat) = self._untagged_response('OK', [None], name)
    if dat[-1]:
        return (typ, dat)
    (typ, dat) = self.noop()
    return self._untagged_response(typ, dat, name)

def response(self, code):
    """Return data for response 'code' if received, or None.

        Old value for response 'code' is cleared.

        (code, [data]) = <instance>.response(code)
        """
    return self._untagged_response(code, [None], code.upper())

def append(self, mailbox, flags, date_time, message):
    """Append message to named mailbox.

        (typ, [data]) = <instance>.append(mailbox, flags, date_time, message)

                All args except `message' can be None.
        """
    name = 'APPEND'
    if not mailbox:
        mailbox = 'INBOX'
    if flags:
        if (flags[0], flags[-1]) != ('(', ')'):
            flags = '(%s)' % flags
    else:
        flags = None
    if date_time:
        date_time = Time2Internaldate(date_time)
    else:
        date_time = None
    literal = MapCRLF.sub(CRLF, message)
    if self.utf8_enabled:
        literal = b'UTF8 (' + literal + b')'
    self.literal = literal
    return self._simple_command(name, mailbox, flags, date_time)

def capability(self):
    """(typ, [data]) = <instance>.capability()
        Fetch capabilities list from server."""
    name = 'CAPABILITY'
    (typ, dat) = self._simple_command(name)
    return self._untagged_response(typ, dat, name)

def check(self):
    """Checkpoint mailbox on server.

        (typ, [data]) = <instance>.check()
        """
    return self._simple_command('CHECK')

def copy(self, message_set, new_mailbox):
    """Copy 'message_set' messages onto end of 'new_mailbox'.

        (typ, [data]) = <instance>.copy(message_set, new_mailbox)
        """
    return self._simple_command('COPY', message_set, new_mailbox)

def create(self, mailbox):
    """Create new mailbox.

        (typ, [data]) = <instance>.create(mailbox)
        """
    return self._simple_command('CREATE', mailbox)

def delete(self, mailbox):
    """Delete old mailbox.

        (typ, [data]) = <instance>.delete(mailbox)
        """
    return self._simple_command('DELETE', mailbox)

def deleteacl(self, mailbox, who):
    """Delete the ACLs (remove any rights) set for who on mailbox.

        (typ, [data]) = <instance>.deleteacl(mailbox, who)
        """
    return self._simple_command('DELETEACL', mailbox, who)

def enable(self, capability):
    """Send an RFC5161 enable string to the server.

        (typ, [data]) = <instance>.enable(capability)
        """
    if 'ENABLE' not in self.capabilities:
        raise IMAP4.error('Server does not support ENABLE')
    (typ, data) = self._simple_command('ENABLE', capability)
    if typ == 'OK' and 'UTF8=ACCEPT' in capability.upper():
        self._mode_utf8()
    return (typ, data)

def getacl(self, mailbox):
    """Get the ACLs for a mailbox.

        (typ, [data]) = <instance>.getacl(mailbox)
        """
    (typ, dat) = self._simple_command('GETACL', mailbox)
    return self._untagged_response(typ, dat, 'ACL')

def getannotation(self, mailbox, entry, attribute):
    """(typ, [data]) = <instance>.getannotation(mailbox, entry, attribute)
        Retrieve ANNOTATIONs."""
    (typ, dat) = self._simple_command('GETANNOTATION', mailbox, entry, attribute)
    return self._untagged_response(typ, dat, 'ANNOTATION')

def login(self, user, password):
    """Identify client using plaintext password.

        (typ, [data]) = <instance>.login(user, password)

        NB: 'password' will be quoted.
        """
    (typ, dat) = self._simple_command('LOGIN', user, self._quote(password))
    if typ != 'OK':
        raise self.error(dat[-1])
    self.state = 'AUTH'
    return (typ, dat)

def login_cram_md5(self, user, password):
    """ Force use of CRAM-MD5 authentication.

        (typ, [data]) = <instance>.login_cram_md5(user, password)
        """
    (self.user, self.password) = (user, password)
    return self.authenticate('CRAM-MD5', self._CRAM_MD5_AUTH)

def _CRAM_MD5_AUTH(self, challenge):
    """ Authobject to use with CRAM-MD5 authentication. """
    import hmac
    pwd = self.password.encode('utf-8') if isinstance(self.password, str) else self.password
    return self.user + ' ' + hmac.HMAC(pwd, challenge, 'md5').hexdigest()

def myrights(self, mailbox):
    """Show my ACLs for a mailbox (i.e. the rights that I have on mailbox).

        (typ, [data]) = <instance>.myrights(mailbox)
        """
    (typ, dat) = self._simple_command('MYRIGHTS', mailbox)
    return self._untagged_response(typ, dat, 'MYRIGHTS')

def noop(self):
    """Send NOOP command.

        (typ, [data]) = <instance>.noop()
        """
    if __debug__:
        if self.debug >= 3:
            self._dump_ur(self.untagged_responses)
    return self._simple_command('NOOP')

def rename(self, oldmailbox, newmailbox):
    """Rename old mailbox name to new.

        (typ, [data]) = <instance>.rename(oldmailbox, newmailbox)
        """
    return self._simple_command('RENAME', oldmailbox, newmailbox)

def search(self, charset, *criteria):
    """Search mailbox for matching messages.

        (typ, [data]) = <instance>.search(charset, criterion, ...)

        'data' is space separated list of matching message numbers.
        If UTF8 is enabled, charset MUST be None.
        """
    name = 'SEARCH'
    if charset:
        if self.utf8_enabled:
            raise IMAP4.error('Non-None charset not valid in UTF8 mode')
        (typ, dat) = self._simple_command(name, 'CHARSET', charset, *criteria)
    else:
        (typ, dat) = self._simple_command(name, *criteria)
    return self._untagged_response(typ, dat, name)

def select(self, mailbox='INBOX', readonly=False):
    """Select a mailbox.

        Flush all untagged responses.

        (typ, [data]) = <instance>.select(mailbox='INBOX', readonly=False)

        'data' is count of messages in mailbox ('EXISTS' response).

        Mandated responses are ('FLAGS', 'EXISTS', 'RECENT', 'UIDVALIDITY'), so
        other responses should be obtained via <instance>.response('FLAGS') etc.
        """
    self.untagged_responses = {}
    self.is_readonly = readonly
    if readonly:
        name = 'EXAMINE'
    else:
        name = 'SELECT'
    (typ, dat) = self._simple_command(name, mailbox)
    if typ != 'OK':
        self.state = 'AUTH'
        return (typ, dat)
    self.state = 'SELECTED'
    if 'READ-ONLY' in self.untagged_responses and (not readonly):
        if __debug__:
            if self.debug >= 1:
                self._dump_ur(self.untagged_responses)
        raise self.readonly('%s is not writable' % mailbox)
    return (typ, self.untagged_responses.get('EXISTS', [None]))

def setacl(self, mailbox, who, what):
    """Set a mailbox acl.

        (typ, [data]) = <instance>.setacl(mailbox, who, what)
        """
    return self._simple_command('SETACL', mailbox, who, what)

def setannotation(self, *args):
    """(typ, [data]) = <instance>.setannotation(mailbox[, entry, attribute]+)
        Set ANNOTATIONs."""
    (typ, dat) = self._simple_command('SETANNOTATION', *args)
    return self._untagged_response(typ, dat, 'ANNOTATION')

def setquota(self, root, limits):
    """Set the quota root's resource limits.

        (typ, [data]) = <instance>.setquota(root, limits)
        """
    (typ, dat) = self._simple_command('SETQUOTA', root, limits)
    return self._untagged_response(typ, dat, 'QUOTA')

def sort(self, sort_criteria, charset, *search_criteria):
    """IMAP4rev1 extension SORT command.

        (typ, [data]) = <instance>.sort(sort_criteria, charset, search_criteria, ...)
        """
    name = 'SORT'
    if (sort_criteria[0], sort_criteria[-1]) != ('(', ')'):
        sort_criteria = '(%s)' % sort_criteria
    (typ, dat) = self._simple_command(name, sort_criteria, charset, *search_criteria)
    return self._untagged_response(typ, dat, name)

def store(self, message_set, command, flags):
    """Alters flag dispositions for messages in mailbox.

        (typ, [data]) = <instance>.store(message_set, command, flags)
        """
    if (flags[0], flags[-1]) != ('(', ')'):
        flags = '(%s)' % flags
    (typ, dat) = self._simple_command('STORE', message_set, command, flags)
    return self._untagged_response(typ, dat, 'FETCH')

def subscribe(self, mailbox):
    """Subscribe to new mailbox.

        (typ, [data]) = <instance>.subscribe(mailbox)
        """
    return self._simple_command('SUBSCRIBE', mailbox)

def uid(self, command, *args):
    """Execute "command arg ..." with messages identified by UID,
                rather than message number.

        (typ, [data]) = <instance>.uid(command, arg1, arg2, ...)

        Returns response appropriate to 'command'.
        """
    command = command.upper()
    if not command in Commands:
        raise self.error('Unknown IMAP4 UID command: %s' % command)
    if self.state not in Commands[command]:
        raise self.error('command %s illegal in state %s, only allowed in states %s' % (command, self.state, ', '.join(Commands[command])))
    name = 'UID'
    (typ, dat) = self._simple_command(name, command, *args)
    if command in ('SEARCH', 'SORT', 'THREAD'):
        name = command
    else:
        name = 'FETCH'
    return self._untagged_response(typ, dat, name)

def unsubscribe(self, mailbox):
    """Unsubscribe from old mailbox.

        (typ, [data]) = <instance>.unsubscribe(mailbox)
        """
    return self._simple_command('UNSUBSCRIBE', mailbox)

